import React, { useEffect, useState } from "react";
import { auth } from "../firebase"; // Your firebase config with auth initialized
import NavBar from "../Components/NavBar";

export default function Kids() {
  const [accepted, setAccepted] = useState(null); // null = loading, false = no access, true = access

  useEffect(() => {
    const checkAcceptance = async () => {
      const user = auth.currentUser;
      if (!user) {
        setAccepted(false);
        return;
      }
      try {
        // Refresh token to get latest claims
        const idTokenResult = await user.getIdTokenResult(true);
        const isAccepted = idTokenResult.claims.accepted || false;
        setAccepted(isAccepted);
      } catch (err) {
        setAccepted(false);
      }
    };
    checkAcceptance();
  }, []);

  if (accepted === null) {
    return (
      <div>
        <NavBar />
        <p>Checking access...</p>
      </div>
    );
  }

  if (!accepted) {
    return (
      <div>
        <NavBar />
        <p style={{ padding: "20px", fontSize: "18px" }}>
          Wait until aromi accepts you.
        </p>
      </div>
    );
  }

  // If accepted, render your existing kids.js content here (the content from original kids.js)

  return (
    <div className="kids-container">
      <NavBar />
      {/* Insert the rest of your kids.js content here */}
      <h1>Welcome to the Kids Section</h1>
      {/* ... your kids page content below ... */}
    </div>
  );
}
